function validate([grid]) {
  if (!Array.isArray(grid) || grid.length !== 3) return 'grid has exactly 3 rows.';
  for (const line of grid) {
    if (!Array.isArray(line) || line.length !== 3) return 'Each row has exactly 3 cells.';
    if (line.some(cell => cell !== 'B' && cell !== 'W')) return "Each cell is 'B' or 'W'.";
  }
  return null;
}

