function canMakeSquare(grid) {
  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 2; col++) {
      let black = 0;
      for (const [dr, dc] of [[0, 0], [0, 1], [1, 0], [1, 1]]) {
        if (grid[row + dr][col + dc] === 'B') black++;
      }
      if (black !== 2) return true;
    }
  }
  return false;
}

