function canMakeSquare(grid) {
  // Try every option (no repaint, or repaint one of the nine cells) and look for a one-color 2 by 2 block.
  const uniform = g => [0, 1].some(r => [0, 1].some(c => g[r][c] === g[r][c + 1] && g[r][c] === g[r + 1][c] && g[r][c] === g[r + 1][c + 1]));
  if (uniform(grid)) return true;
  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 3; c++) {
      const copy = grid.map(line => line.slice());
      copy[r][c] = copy[r][c] === 'B' ? 'W' : 'B';
      if (uniform(copy)) return true;
    }
  }
  return false;
}

