function generate(rand, size) {
  // Every grid is 3 by 3, so both sizes draw a random coloring; a bias toward one color varies the shapes.
  const bias = size === 'large' ? 0.5 : 0.2 + rand() * 0.6;
  const grid = Array.from({ length: 3 }, () => Array.from({ length: 3 }, () => (rand() < bias ? 'B' : 'W')));
  return [grid];
}
